/**
 * Spaced repetition: the FSRS-6 memory model with day-level scheduling (plan 10.6/2, FR-94).
 *
 * Source of the formulas: open-spaced-repetition "The Algorithm" (FSRS-6, 21 weights, default decay 0.1542),
 * the same model that ts-fsrs 6.0.0 (MIT) ships. This module is the "long term" scheduler variant (no
 * minute-level learning steps): every rating schedules a whole number of days and a card is in the Review state
 * after its first rating. It is dependency free on purpose; `fsrs.test.ts` compares it with reference
 * results generated by ts-fsrs 6.0.0 (docs/istekler/pratik-ts-fsrs.md).
 *
 * Deliberate differences from the library defaults:
 * - fuzz is off, so the same history always gives the same schedule (testable and explainable);
 * - the day boundary is the Turkish calendar day (UTC+3) instead of UTC, so a card reviewed at 23:30 and again
 *   at 00:30 local time is one day apart;
 * - no leech or relearning step handling; a failed card is rescheduled for at least one day, and the study
 *   session itself shows it again in the same sitting (oturum.ts).
 */

export const Derece = { Tekrar: 1, Zor: 2, Iyi: 3, Kolay: 4 } as const;
export type Derece = (typeof Derece)[keyof typeof Derece];
export const dereceler: readonly Derece[] = [1, 2, 3, 4];

export const Durum = { Yeni: 0, Ogrenme: 1, Gozden: 2, YenidenOgrenme: 3 } as const;
export type Durum = (typeof Durum)[keyof typeof Durum];

/** FSRS-6 default weights (w0..w20). */
export const varsayilanAgirliklar: readonly number[] = Object.freeze([
  0.212, 1.2931, 2.3065, 8.2956, 6.4133, 0.8334, 3.0194, 0.001, 1.8722, 0.1666, 0.796, 1.4835, 0.0614, 0.2629,
  1.6483, 0.6014, 1.8729, 0.5425, 0.0912, 0.0658, 0.1542,
]);

export interface Ayarlar {
  /** Target retention, plan 10.6/2 default 0.90. Accepted range 0.70 to 0.97. */
  hedefHatirlama: number;
  /** Upper bound of one interval in days. */
  enFazlaAralik: number;
  agirliklar: readonly number[];
  /** Minutes added to UTC to find the calendar day. Turkey is a fixed UTC+3. */
  gunKaydirmaDk: number;
}

export const varsayilanAyarlar: Ayarlar = Object.freeze({
  hedefHatirlama: 0.9,
  enFazlaAralik: 36500,
  agirliklar: varsayilanAgirliklar,
  gunKaydirmaDk: 180,
});

/** Persisted state of one card for one user; maps onto the card_reviews columns. */
export interface KartDurumu {
  due: Date;
  stability: number;
  difficulty: number;
  elapsedDays: number;
  scheduledDays: number;
  reps: number;
  lapses: number;
  state: Durum;
  lastReview: Date | null;
}

const S_MIN = 0.001;
const S_MAX = 36500;
const GUN_MS = 86_400_000;

const sinirla = (v: number, alt: number, ust: number) => Math.min(Math.max(v, alt), ust);
const yuvarla = (v: number, basamak: number) => {
  const f = 10 ** basamak;
  return Math.round(v * f) / f;
};

export function yeniKart(simdi: Date): KartDurumu {
  return {
    due: simdi,
    stability: 0,
    difficulty: 0,
    elapsedDays: 0,
    scheduledDays: 0,
    reps: 0,
    lapses: 0,
    state: Durum.Yeni,
    lastReview: null,
  };
}

export function ayarlariDogrula(a: Ayarlar): Ayarlar {
  if (a.agirliklar.length !== 21 || a.agirliklar.some((w) => !Number.isFinite(w))) {
    throw new RangeError('FSRS-6 needs exactly 21 finite weights');
  }
  if (!(a.hedefHatirlama >= 0.7 && a.hedefHatirlama <= 0.97)) {
    throw new RangeError('desired retention must be between 0.70 and 0.97');
  }
  if (!Number.isInteger(a.enFazlaAralik) || a.enFazlaAralik < 1 || a.enFazlaAralik > S_MAX) {
    throw new RangeError('maximum interval must be an integer between 1 and 36500');
  }
  return a;
}

function bozunum(w: readonly number[]) {
  const decay = -(w[20] as number);
  const factor = yuvarla(Math.exp(Math.log(0.9) / decay) - 1, 8);
  return { decay, factor };
}

/** Probability of recall after `gun` days for a card of stability `s` (forgetting curve). */
export function hatirlanabilirlik(gun: number, s: number, w: readonly number[] = varsayilanAgirliklar) {
  const { decay, factor } = bozunum(w);
  return yuvarla(Math.pow(1 + (factor * gun) / s, decay), 8);
}

const baslangicKararliligi = (w: readonly number[], g: Derece) => sinirla(w[g - 1] as number, S_MIN, S_MAX);
const baslangicZorlugu = (w: readonly number[], g: number) =>
  yuvarla((w[4] as number) - Math.exp((g - 1) * (w[5] as number)) + 1, 8);

function sonrakiZorluk(w: readonly number[], d: number, g: Derece) {
  const delta = -(w[6] as number) * (g - 3);
  const sonraki = d + yuvarla((delta * (10 - d)) / 9, 8);
  const w7 = w[7] as number;
  const ortalamayaDonus = yuvarla(w7 * baslangicZorlugu(w, 4) + (1 - w7) * sonraki, 8);
  return sinirla(ortalamayaDonus, 1, 10);
}

function hatirlamaKararliligi(w: readonly number[], d: number, s: number, r: number, g: Derece) {
  const zorCezasi = g === Derece.Zor ? (w[15] as number) : 1;
  const kolayCarpani = g === Derece.Kolay ? (w[16] as number) : 1;
  return yuvarla(
    sinirla(
      s *
        (1 +
          Math.exp(w[8] as number) *
            (11 - d) *
            Math.pow(s, -(w[9] as number)) *
            (Math.exp((1 - r) * (w[10] as number)) - 1) *
            zorCezasi *
            kolayCarpani),
      S_MIN,
      S_MAX,
    ),
    8,
  );
}

function unutmaKararliligi(w: readonly number[], d: number, s: number, r: number) {
  return yuvarla(
    sinirla(
      (w[11] as number) *
        Math.pow(d, -(w[12] as number)) *
        (Math.pow(s + 1, w[13] as number) - 1) *
        Math.exp((1 - r) * (w[14] as number)),
      S_MIN,
      S_MAX,
    ),
    8,
  );
}

function sonrakiBellek(
  w: readonly number[],
  bellek: { difficulty: number; stability: number },
  gun: number,
  g: Derece,
) {
  const { difficulty: d, stability: s } = bellek;
  if (d === 0 && s === 0) {
    return { difficulty: sinirla(baslangicZorlugu(w, g), 1, 10), stability: baslangicKararliligi(w, g) };
  }
  const r = hatirlanabilirlik(gun, s, w);
  let yeniS: number;
  if (g === Derece.Tekrar) {
    const basarisizSonra = unutmaKararliligi(w, d, s, r);
    // Without short term steps w17 and w18 are zero, so the lower bound is s itself.
    yeniS = sinirla(yuvarla(s / Math.exp(0), 8), S_MIN, basarisizSonra);
  } else {
    yeniS = hatirlamaKararliligi(w, d, s, r, g);
  }
  return { difficulty: sonrakiZorluk(w, d, g), stability: yeniS };
}

function aralik(a: Ayarlar, s: number) {
  const { decay, factor } = bozunum(a.agirliklar);
  return Math.max(Math.round((s / factor) * (Math.pow(a.hedefHatirlama, 1 / decay) - 1)), 1);
}

/** Whole calendar days between two instants, on the calendar of the configured offset. */
export function takvimGunuFarki(onceki: Date, simdi: Date, kaydirmaDk: number) {
  const gun = (t: Date) => Math.floor((t.getTime() + kaydirmaDk * 60_000) / GUN_MS);
  return gun(simdi) - gun(onceki);
}

export type OnizlemeSonucu = Record<Derece, KartDurumu>;

/** The four possible next states of a card, one per rating (ts-fsrs `repeat`). */
export function onizle(kart: KartDurumu, simdi: Date, ayar: Ayarlar = varsayilanAyarlar): OnizlemeSonucu {
  ayarlariDogrula(ayar);
  const w = ayar.agirliklar;
  const yeni = kart.state === Durum.Yeni;
  const gecen =
    !yeni && kart.lastReview ? Math.max(0, takvimGunuFarki(kart.lastReview, simdi, ayar.gunKaydirmaDk)) : 0;
  const adaylar = dereceler.map((g) => {
    const bellek = sonrakiBellek(w, { difficulty: kart.difficulty, stability: kart.stability }, gecen, g);
    return { g, bellek, ham: aralik(ayar, bellek.stability) };
  });
  // Intervals stay strictly increasing from Again to Easy and are capped (ts-fsrs calculateScheduleDays).
  const enFazla = ayar.enFazlaAralik;
  const gunler: number[] = [];
  adaylar.forEach((a, i) => {
    const onceki = gunler[i - 1];
    gunler.push(
      i === 0
        ? Math.min(a.ham, enFazla)
        : Math.min(Math.max(a.ham, (onceki as number) === 0 ? 0 : (onceki as number) + 1), enFazla),
    );
  });
  const sonuc = {} as OnizlemeSonucu;
  adaylar.forEach((a, i) => {
    const sureGun = gunler[i] as number;
    sonuc[a.g] = {
      due: new Date(simdi.getTime() + sureGun * GUN_MS),
      stability: a.bellek.stability,
      difficulty: a.bellek.difficulty,
      elapsedDays: gecen,
      scheduledDays: sureGun,
      reps: kart.reps + 1,
      lapses: kart.lapses + (!yeni && a.g === Derece.Tekrar ? 1 : 0),
      state: Durum.Gozden,
      lastReview: simdi,
    };
  });
  return sonuc;
}

/** Apply one rating (1 Again, 2 Hard, 3 Good, 4 Easy) and return the new state. */
export function incele(
  kart: KartDurumu,
  derece: Derece,
  simdi: Date,
  ayar: Ayarlar = varsayilanAyarlar,
): KartDurumu {
  if (!dereceler.includes(derece)) throw new RangeError(`rating must be 1 to 4, got ${String(derece)}`);
  return onizle(kart, simdi, ayar)[derece];
}

/** Retrievability of a stored card right now; null for a card that has never been reviewed. */
export function simdikiHatirlanabilirlik(kart: KartDurumu, simdi: Date, ayar: Ayarlar = varsayilanAyarlar) {
  if (kart.state === Durum.Yeni || !kart.lastReview) return null;
  const gun = Math.max(0, (simdi.getTime() - kart.lastReview.getTime()) / GUN_MS);
  return hatirlanabilirlik(gun, kart.stability, ayar.agirliklar);
}

/** Due when the due instant has passed; the calendar day, not the hour, decides (all of today's cards are due). */
export function vadesiGeldiMi(kart: KartDurumu, simdi: Date, ayar: Ayarlar = varsayilanAyarlar) {
  if (kart.state === Durum.Yeni) return false;
  return takvimGunuFarki(kart.due, simdi, ayar.gunKaydirmaDk) >= 0;
}
